// Five front-desk automations: what each is worth to the client a month, and what it costs you to run.
// Assumptions are deliberately modest. Change them for your trade.
const f = $input.first().json;
const n = k => Number(f[k]) || 0;
const leads = n('New leads a month'), missedWeek = n('Calls missed a week');
const job = n('Average job ($)'), jobs = n('Jobs a month'), hour = n('An hour of staff time ($)');
const missedMonth = Math.round(missedWeek * 4.33);

// Value a month (revenue, not profit)
const leadReply = Math.floor(leads * 0.05) * job;          // 1 extra job per 20 leads answered in a minute
const missedCalls = Math.floor(missedMonth * 0.10) * job;  // 1 in 10 missed callers booked by text
const reviews = 1 * job;                                   // softest number: 1 extra job a month
const reminders = Math.floor(jobs * 0.03) * job;           // 3 in 100 no-shows saved
const invoices = 5 * hour;                                 // time only: 5 hours a month of chasing
const value = leadReply + missedCalls + reviews + reminders + invoices;

// Cost to run a month (list prices, rounded up)
const AI = 0.01, TEXT = 0.02, NUMBER = 5, HOSTING = 20;   // per AI reply, per text all in, number + US texting registration, n8n cloud
const cost = leads * AI + (missedMonth * 2 * TEXT + NUMBER) + 1 + jobs * 2 * TEXT + 1 + HOSTING;

const price = 500;
const usd = x => '$' + Math.round(x).toLocaleString('en-US');
return [{ json: { business: f['Business name'], leadReply, missedCalls, reviews, reminders, invoices, value, cost: Math.round(cost), price, multiple: Math.round(value / price * 10) / 10, margin: Math.round(price - cost),
  line: `Lead reply ${usd(leadReply)} · Missed calls ${usd(missedCalls)} · Reviews ${usd(reviews)} · Reminders ${usd(reminders)} · Invoices ${usd(invoices)}` } }];
